def balanced(text: str) -> bool:
    stack = []
    in_quote = None  # None, or the quote character (' or ")
    escaped = False

    matching = {
        ')': '(',
        ']': '[',
        '}': '{'
    }

    for char in text:
        if in_quote is not None:
            if escaped:
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == in_quote:
                in_quote = None
            continue
        else:
            if char in ('\'', '"'):
                in_quote = char
                escaped = False
                continue
            elif char == '\\':
                # A backslash outside of quotes could be considered raw syntax,
                # but typically we just ignore or handle it. To be safe, let's treat it as literal.
                pass

        if char in ('(', '[', '{'):
            stack.append(char)
        elif char in (')', ']', '}'):
            if not stack or stack[-1] != matching[char]:
                return False
            stack.pop()

    if in_quote is not None:
        return False

    return len(stack) == 0
